import{_ as t,o as a,c as o,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"API Gateway JWT Verification, Header Sanitization & Rate Limiting","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/01-identity-gateway/gateway-jwt-and-rate-limiting/spec.md","filePath":"feature/modules/01-identity-gateway/gateway-jwt-and-rate-limiting/spec.md"}'),r={name:"feature/modules/01-identity-gateway/gateway-jwt-and-rate-limiting/spec.md"};function n(d,e,c,s,l,g){return a(),o("div",null,[...e[0]||(e[0]=[i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="api-gateway-jwt-verification-header-sanitization-rate-limiting" tabindex="-1">API Gateway JWT Verification, Header Sanitization &amp; Rate Limiting <a class="header-anchor" href="#api-gateway-jwt-verification-header-sanitization-rate-limiting" aria-label="Permalink to &quot;API Gateway JWT Verification, Header Sanitization &amp; Rate Limiting&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>gateway-jwt-and-rate-limiting</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>01-identity-gateway</code> — Identity, API Gateway &amp; Edge Security</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Guest, Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>gateway-ci-jwt</code>, <code>InboundSecurityWebFilter</code>, <code>JwtAuthFilterGatewayFilterFactory</code>, <code>RateLimitGatewayFilterFactory</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/01-authentication/README.html">3.2 Authentication &amp; Authorization</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Provide unified edge security across <code>brandhub-api-gateway</code> (Spring Cloud Gateway WebFlux): stripping spoofed internal identity headers (<code>InboundSecurityWebFilter</code>), validating HMAC-SHA256 / RSA Bearer JWTs (<code>JwtAuthFilterGatewayFilterFactory</code>), enforcing Redis token-bucket rate limits (<code>RateLimitGatewayFilterFactory</code>), injecting correlation IDs (<code>RequestIdWebFilter</code>), and ensuring deterministic CI/production secret configuration.</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As any platform actor (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>), I want every API call routed through <code>brandhub-api-gateway</code> to enforce consistent JWT authentication, anti-spoofing header hygiene, and abuse rate limiting so downstream microservices remain protected.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Inbound Header Sanitization (<code>InboundSecurityWebFilter</code>):</strong> Strips caller-supplied <code>X-User-Id</code>, <code>X-User-Role</code>, <code>X-User-Email</code>, <code>X-Workspace-Id</code>, and <code>X-Internal-Service-Key</code> headers at the edge before JWT evaluation so external clients can never impersonate internal actors (<code>X-AI-Workspace-Id</code> is validated separately against DB membership in <code>business-service</code>).</li><li><strong>Stateless JWT Verification (<code>JwtAuthFilterGatewayFilterFactory</code>):</strong> Validates signature, <code>exp</code>, <code>iat</code>, and token type (<code>access</code> vs <code>refresh</code>) on protected routes while whitelisting public endpoints (<code>/api/v1/auth/login</code>, <code>/register</code>, <code>/public/**</code>, <code>/api/v1/billing/webhooks/sepay</code>, <code>/api/monitoring/heartbeat</code>).</li><li><strong>Redis Distributed Rate Limiting (<code>RateLimitGatewayFilterFactory</code>):</strong> Enforces per-IP and per-authenticated-user token-bucket limits on auth/OTP, AI Studio, and public share endpoints, returning <code>429 TOO_MANY_REQUESTS</code> with <code>Retry-After</code> headers when exceeded.</li><li><strong>Request Correlation &amp; CI Deterministic Boot (<code>gateway-ci-jwt</code>, <code>RequestIdWebFilter</code>, <code>LoggingGlobalFilter</code>):</strong> Propagates or mints <code>X-Request-Id</code> across all upstream routes (<code>business</code>, <code>publisher</code>, <code>ai</code>) and validates <code>JWT_SECRET</code> minimum entropy (<code>&gt;= 256-bit</code>) in CI and production profiles.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>common.errors.{unauthorized,rateLimited,networkError}</code> in <code>src/i18n/locales/{vi,en}/common.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>src/services/api.ts</code> (<code>401</code> refresh interceptor &amp; <code>429</code> toast handler)</li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/services/api.ts</code> (<code>expo-secure-store</code> token refresh queue &amp; <code>429</code> error mapping)</li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>InboundSecurityWebFilter (Global Order HIGHEST)</code></td><td style="text-align:left;">All Edge Traffic</td><td style="text-align:left;"><code>brandhub-api-gateway</code> -&gt; strips forged <code>X-User-*</code> / <code>X-Internal-*</code> headers</td></tr><tr><td style="text-align:left;"><code>JwtAuthFilterGatewayFilterFactory</code></td><td style="text-align:left;">Bearer JWT Routes</td><td style="text-align:left;"><code>brandhub-api-gateway</code> -&gt; validates JWT &amp; injects verified <code>X-User-Id</code> / <code>X-User-Role</code></td></tr><tr><td style="text-align:left;"><code>RateLimitGatewayFilterFactory</code></td><td style="text-align:left;">IP / User Bucket</td><td style="text-align:left;"><code>brandhub-api-gateway</code> + Redis -&gt; enforces burst/replenish rate limits (<code>429</code> on overflow)</td></tr><tr><td style="text-align:left;"><code>RequestIdWebFilter + LoggingGlobalFilter</code></td><td style="text-align:left;">All Routes</td><td style="text-align:left;"><code>brandhub-api-gateway</code> -&gt; binds <code>X-Request-Id</code> &amp; structured latency/status logs</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Redis Temporarily Unreachable:</strong> Rate limiter fails open/bounded with circuit warning on non-auth read routes while keeping strict login/OTP brute-force protection.</li><li><strong>Refresh Token Replayed as Access Token:</strong> Rejected <code>401 UNAUTHORIZED</code> by claim-type check at the Gateway.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/01-authentication/README.html">3.2 Authentication &amp; Authorization</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA 02 Authentication &amp; Profile</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const p=t(r,[["render",n]]);export{h as __pageData,p as default};
